{{- /*
  The nginx redirect map for renamed gallery images — `nginxmap` output format in
  hugo.yaml, written to /_nginx/gallery-image-redirects.map and read by the
  `map $gallery_stem $gallery_new_stem` block in the nginx.conf of Web-Services/homepage and homepage-tor
  (docs/concepts/gallery-metadata-yaml-only.md §5, "The nginx side").

  One line per old file stem -> the photo's current file slug. Keys are STEMS, not
  URLs: nginx splits `/images/gallery/<stem>(_hu_<hash>)?.<ext>` and carries the
  hash over, because `_hu_<hash>` depends on the pixels and the spec, never on the
  name — so one line covers the published original and every variant.

  Two kinds of key:
    - the store filename's stem (`DSC_2632`): what every image URL was until the
      build started publishing under the slug;
    - each `slugAliases` entry: a former page slug. After a reworded English
      title, the old slug added there (to keep the page URL alive) is also the old
      FILE slug, so the same hand edit keeps the old image URLs alive.

  Stop-the-build rules, because nginx would otherwise get them silently wrong:
    - nginx matches map strings IGNORING CASE, so keys are compared lowercased;
    - a key equal to a LIVE file slug would redirect a file that exists (and the
      live file to itself, a loop) — an error, unless it is the photo's own slug,
      which is simply skipped;
    - one key pointing at two different photos is an error.
  Keys are double-quoted (125 store stems contain spaces, one an apostrophe);
  nginx matches them against the decoded $uri, so they are written unencoded.
*/ -}}
{{- $meta := partialCached "gallery-meta.html" . -}}
{{- $live := dict -}}
{{- range $meta.bySrc -}}
  {{- $live = merge $live (dict (lower .fileSlug) .src) -}}
{{- end -}}
{{- $seen := dict -}}
{{- $lines := slice -}}
{{- range $src, $e := $meta.bySrc -}}
  {{- $keys := slice (strings.TrimSuffix (path.Ext $src) $src) | append ($e.slugAliases | default slice) -}}
  {{- range $k := $keys -}}
    {{- $lk := lower $k -}}
    {{- if ne $lk $e.fileSlug -}}
      {{- with index $live $lk -}}
        {{- errorf "nginx map: %q (old name of %q) is the live file slug of %q — it would redirect a file that exists" $k $src . -}}
      {{- else -}}
        {{- with index $seen $lk -}}
          {{- if ne . $e.fileSlug -}}
            {{- errorf "nginx map: %q is an old name of two photos (-> %q and %q)" $k . $e.fileSlug -}}
          {{- end -}}
        {{- else -}}
          {{- $seen = merge $seen (dict $lk $e.fileSlug) -}}
          {{- $q := replace (replace $k `\` `\\`) `"` `\"` -}}
          {{- $lines = $lines | append (printf "\"%s\" %s;" $q $e.fileSlug) -}}
        {{- end -}}
      {{- end -}}
    {{- end -}}
  {{- end -}}
{{- end -}}
# Generated by Hugo from data/gallery.yaml (layouts/_default/home.nginxmap.map).
# Old gallery image stem -> current file slug. Do not edit; do not serve.
{{ delimit $lines "\n" }}
